class Media {
  constructor(titre, duree) {
    this.titre = titre;
    this.duree = duree;
    this.vues = 0;
  }
  incrementerVues() {
    this.vues++;
  }
  get dureeFormatee() {
    return Math.floor(this.duree / 60) + " min";
  }
}

const film = new Media("Film", 185);
film.incrementerVues();
film.incrementerVues();
console.log(film.vues);
console.log(film.dureeFormatee);

