class Media {
  #duree;
  constructor(titre, duree) {
    this.titre = titre;
    this.duree = duree;
  }
  get duree() {
    return this.#duree;
  }
  set duree(v) {
    if (typeof v !== "number" || v <= 0) throw new RangeError("Durée invalide");
    this.#duree = v;
  }
}

const m = new Media("A", 120);
console.log(m.duree);
try {
  m.duree = -10;
} catch (e) {
  console.log(e.message);
}

