class Media {
  constructor(titre, auteur) {
    this.titre = titre;
    this.auteur = auteur;
  }
  decrire() {
    return this.titre + " - " + this.auteur;
  }
}

class Video extends Media {
  decrire() {
    return "[video] " + super.decrire();
  }
}

class Image extends Media {
  decrire() {
    return "[image] " + super.decrire();
  }
}

const galerie = [new Video("Ouverture", "Lina"), new Image("Affiche", "Sam")];
for (const m of galerie) console.log(m.decrire());

